2175	/// INTERVALO DE DATA's own 3 choices (spec-5-2; `prototype-extract.md`) —
2176	/// each computes its own `dateFrom`/`dateTo` pair via [rangeFrom]. [allTime]
2177	/// is itself a selectable choice meaning "no date filter at all", not some
2178	/// maximal range — it resolves to `(null, null)`.
2179	///
2180	/// Lives in the domain layer (RNF06) rather than alongside
2181	/// `EntriesFilterSheet` so `MeusRegistrosCubit` can store the selected
2182	/// preset directly (code-review fix: re-deriving it from `dateFrom` by
2183	/// equality match against a freshly recomputed "today" boundary goes stale
2184	/// the moment a day/week/month boundary rolls over while the filter stays
2185	/// active) without the cubit importing a presentation-layer widget file.
2186	/// UI-facing copy (`label`) stays out of this enum, same split
2187	/// `EntrySource`/`entrySourceLabel` already uses — see
2188	/// `entries_filter_sheet.dart`'s own `dateRangePresetLabel`.
2189	enum DateRangePreset {
2190	  allTime,
2191	  thisWeek,
2192	  thisMonth;
2193	
2194	  /// This preset's own `(dateFrom, dateTo)` pair, anchored to [now] (a
2195	  /// parameter only so a test can pin it — every real call site passes
2196	  /// `DateTime.now()`). `dateTo` is always [now] itself — "through right
2197	  /// now" — `docs/input/` is silent on inclusive/exclusive bounds here
2198	  /// (AGENTS.md policy: "decide and proceed"). `dateFrom` is local
2199	  /// midnight of the Monday starting this week, or the 1st of this
2200	  /// calendar month.
2201	  (DateTime?, DateTime?) rangeFrom(DateTime now) {
2202	    final today = DateTime(now.year, now.month, now.day);
2203	    switch (this) {
2204	      case DateRangePreset.allTime:
2205	        return (null, null);
2206	      case DateRangePreset.thisWeek:
2207	        return (today.subtract(Duration(days: today.weekday - 1)), now);
2208	      case DateRangePreset.thisMonth:
2209	        return (DateTime(today.year, today.month), now);
2210	    }
2211	  }
2212	}
